.doctor-schedule-close{float:right;border:0;background:transparent;font-size:24px;cursor:pointer}@media(max-width:700px){.doctor-waiting-summary{grid-template-columns:repeat(2,minmax(0,1fr))}.doctor-schedule-modal dl{grid-template-columns:1fr}}
