            <?php else: ?><tr><td><?= tdc_e($v['VisitReference']) ?></td><td><?= tdc_e($v['PatientName']) ?></td><td><?= tdc_e($v['Gender']) ?></td><td><?= tdc_e((string)$v['Age']) ?></td><td><?= tdc_e($v['PatientPhone']) ?></td><td><?= tdc_e(date('Y-m-d', strtotime((string)$v['VisitDate']))) ?></td><td><?= tdc_badge($v['PaymentStatus']) ?></td><td><?= tdc_e(number_format((float)($v['DueBalance'] ?? 0), 2)) ?></td><td><?= tdc_badge($v['QueueStatus']) ?></td><td class="no-print"><div class="row-actions">
