                <?php if (in_array($v['QueueStatus'], ['Waiting', 'Pending Payment'], true) && tdc_can('consultations.edit')): ?><form method="post" action="doctors.php?workspace=1"><input type="hidden" name="csrf_token" value="<?= tdc_e($csrfToken) ?>"><input type="hidden" name="VisitID" value="<?= (int)$v['VisitID'] ?>"><input type="hidden" name="PatientID" value="<?= (int)$v['PatientID'] ?>"><input type="hidden" name="DoctorID" value="<?= (int)$v['DoctorID'] ?>"><input type="hidden" name="portal_action" value="start"><button type="submit" class="btn-sm btn-primary" data-doctor-action="call" data-visit-id="<?= (int)$v['VisitID'] ?>" data-patient-id="<?= (int)$v['PatientID'] ?>" title="Call / Start">Call</button></form><?php endif; ?>
                <button type="button" class="btn-sm" data-doctor-action="consultation" data-visit-id="<?= (int)$v['VisitID'] ?>" data-patient-id="<?= (int)$v['PatientID'] ?>"><?= in_array($v['QueueStatus'], ['Waiting', 'Pending Payment'], true) ? 'Start Consultation' : ($v['QueueStatus'] === 'Completed' ? 'View Consultation' : 'Continue Consultation') ?></button>
                <button type="button" class="btn-sm btn-secondary" data-doctor-action="history" data-visit-id="<?= (int)$v['VisitID'] ?>" data-patient-id="<?= (int)$v['PatientID'] ?>" title="Medical History">History</button>
                <?php if ((string)($v['EditableLaboratoryID'] ?? '') !== ''): ?><button type="button" class="btn-sm btn-success" data-doctor-action="edit_lab" data-reference="<?= tdc_e((string)$v['EditableLaboratoryID']) ?>" data-visit-id="<?= (int)$v['VisitID'] ?>" data-patient-id="<?= (int)$v['PatientID'] ?>" title="Edit Lab Request">Edit Lab</button><?php else: ?><button type="button" class="btn-sm btn-success" data-doctor-action="lab" data-visit-id="<?= (int)$v['VisitID'] ?>" data-patient-id="<?= (int)$v['PatientID'] ?>" title="<?= $visitReadyForOrders ? 'Request Lab' : 'Complete the consultation assessment before requesting laboratory tests.' ?>" <?= $visitReadyForOrders ? '' : 'disabled aria-disabled="true"' ?>>Lab</button><?php endif; ?>
