                <button type="button" class="btn-sm btn-clinical" data-doctor-action="results" data-visit-id="<?= (int)$v['VisitID'] ?>" data-patient-id="<?= (int)$v['PatientID'] ?>" title="Lab Results">Results</button>
            </div></td></tr><?php endif; ?>
