<?php if ($waitingSchedule): ?><section class="doctor-schedule-modal" id="doctorScheduleModal" aria-labelledby="doctorScheduleTitle"><button type="button" class="doctor-schedule-close" aria-label="Close">&times;</button><h2 id="doctorScheduleTitle">Visit Details</h2><dl><dt>Visit Ref</dt><dd data-detail="reference"></dd><dt>Patient</dt><dd data-detail="patient"></dd><dt>Date</dt><dd data-detail="date"></dd><dt>Time</dt><dd data-detail="time"></dd><dt>Payment Status</dt><dd><span data-detail="payment" class="doctor-schedule-badge"></span></dd><dt>Due</dt><dd data-detail="due"></dd><dt>Queue Status</dt><dd><span data-detail="status" class="doctor-schedule-badge"></span></dd></dl><button type="button" class="btn btn-secondary doctor-schedule-close">Close</button></section><script>(function(){const modal=document.getElementById('doctorScheduleModal');if(!modal)return;function setBadge(target,value,type){target.textContent=value;target.className='doctor-schedule-badge '+type+'-'+value.toLowerCase().replace(/\s+/g,'-');}document.querySelectorAll('.schedule-details').forEach(function(button){button.addEventListener('click',function(){const payment=modal.querySelector('[data-detail="payment"]');const status=modal.querySelector('[data-detail="status"]');Object.keys(button.dataset).forEach(function(key){const target=modal.querySelector('[data-detail="'+key+'"]');if(!target)return;if(key==='payment')setBadge(target,button.dataset[key],'payment');else if(key==='status')setBadge(target,button.dataset[key],'queue');else target.textContent=button.dataset[key];});modal.classList.add('is-open');});});modal.querySelectorAll('.doctor-schedule-close').forEach(function(button){button.addEventListener('click',function(){modal.classList.remove('is-open');});});})();</script><?php endif; ?>
